(function(){let warned=false;const failure=()=>{window.desktop?.reportIssue();if(warned)return;warned=true;const box=document.createElement('div');box.className='startup-error';box.setAttribute('role','alert');const text=document.createElement('span');text.textContent='界面运行异常，请重新加载。';const button=document.createElement('button');button.textContent='重新加载';button.onclick=()=>window.desktop?.reload();box.append(text,button);document.body.append(box);};window.addEventListener('error',event=>{if(event.error||(event.target?.tagName==='SCRIPT'&&!event.target.dataset.feature))failure();},true);window.addEventListener('unhandledrejection',event=>{if(event.reason?.code==='ABORTED'||event.reason?.code==='STALE_SESSION')return;failure();});})();
